"""ARENA u14 的 10 道测验（沿用旧版题目；解释里的位置引用已改掉）"""
from unitlib import Q
QUIZ = [
  Q('形状 `(5, 3)` 和 `(3,)` 相加，结果是？', ['`(5, 3)`', '报错', '`(3, 5)`', '`(5,)`'], 0, '`(3,)` 补成 `(1, 3)`，再沿第 0 维复制，每一行都加上这个向量。'),
  Q('形状 `(6, 2)` 和 `(6,)` 相加，结果是？', ['`(6, 2)`', '`(6, 6)`', '报错', '`(6,)`'], 2, '从右往左对齐：`(6,)` 对的是最后一维 2，6 ≠ 2 且都不是 1，报错。想按行加应该用 `(6, 1)`。'),
  Q('形状 `(4, 1)` 和 `(4,)` 相加，会怎样？', ['报错', '得到 `(4,)`', '得到 `(4, 1)`', '得到 `(4, 4)`，不报错，但很可能不是想要的结果'], 3, '`(4,)` 补成 `(1, 4)`，和 `(4, 1)` 互相扩展成 `(4, 4)`。这是最隐蔽的广播 bug。'),
  Q('形状 `(2, 1, 4)` 和 `(3, 1)` 相加，结果是？', ['`(2, 3, 4)`', '报错', '`(2, 1, 4)`', '`(3, 2, 4)`'], 0, '`(3, 1)` 补成 `(1, 3, 1)`，逐维取较大者得 `(2, 3, 4)`：两个张量都被扩展了。'),
  Q('`x` 形状 `(3, 1, 5)`，`x.squeeze(0).shape` 是？', ['`(1, 5)`', '`(3, 1, 5)`', '`(3, 5)`', '报错'], 1, '`squeeze(0)` 只在第 0 维长度为 1 时才去掉它。这里第 0 维是 3，所以什么都不做。去掉第 1 维要写 `squeeze(1)`。'),
  Q('`m` 形状 `(3, 4)`，想让每一**行**减去该行的平均值，正确的写法是？', ['`m - m.mean(dim=1)`', '`m - m.mean()`', '`m - m.mean(dim=0)`', '`m - m.mean(dim=1, keepdim=True)`'], 3, '行均值的形状必须是 `(3, 1)` 才能沿每一行广播。不写 `keepdim=True` 得到 `(3,)`，它会去对齐最后一维 4，形状对不上而报错；`mean(dim=0)` 减的是列均值；不带参数的 `mean()` 减的是全局均值。'),
  Q('`Xn` 是行归一化后的矩阵（形状 `(m, d)`），`Xn @ Xn.T` 的 `[i, j]` 元素是什么？', ['第 $i$ 行和第 $j$ 行的余弦相似度', '第 $i$ 行的长度', '第 $i$ 列和第 $j$ 列的差', '总是 1'], 0, '矩阵乘法 `[i, j]` = 第 $i$ 行与 `Xn.T` 第 $j$ 列（即 `Xn` 第 $j$ 行）的点积；两者都是单位向量，所以就是余弦相似度。'),
  Q('直接计算 `t.exp(z) / t.exp(z).sum()`，其中 `z = [1000., 1001., 1002.]`，结果是？', ['正确的概率分布', '`[nan, nan, nan]`，因为 $e^{1000}$ 溢出', '全是 0', '全是 1/3'], 1, '$e^{1000}$ 超出 float32 范围变成 inf，inf / inf = nan。解决办法是先减去最大值。'),
  Q('数值稳定的 softmax 为什么要**减去最大值**？', ['因为这样结果更精确地变成了均匀分布', '因为 softmax 要求输入为负数', '因为分子分母同乘 $e^{-c}$ 结果不变，而减去最大值后指数不会溢出', '因为可以减少计算量'], 2, '减去任何常数 $c$ 都不改变 softmax 的结果；取 $c = \\max z$ 让所有指数 $\\le 0$，避免溢出。'),
  Q('`logp` 形状 `(batch, n_classes)` 是 log-softmax 的结果，`target` 是每个样本的正确类别。交叉熵损失怎么算？', ['`logp.mean()`', '`logp[:, target].sum()`', '`-logp.max(dim=1).values.mean()`', '`-logp[t.arange(batch), target].mean()`'], 3, '用整数数组索引取出每个样本「正确类别」的 log 概率，取负、求平均。`logp[:, target]` 会取出 `(batch, batch)` 的矩阵，不对；取最大值得到的是模型最自信的类别，而不是正确类别。'),
]
